import random

def generate_random_integers(num_ints):
    with open(""random_ints.txt"", ""w"") as file:
        for _ in range(num_ints):
            file.write(str(random.randint(0, 100)) + ""\n"")

def read_file():
    with open(""random_ints.txt"", ""r"") as file:
        ints = [int(line) for line in file]
    return ints

def sort_integers(ints):
    return sorted(ints, reverse=True)

def find_sum_of_top_three(sorted_ints):
    top_three = sorted_ints[:3]
    return sum(top_three)

if __name__ == ""__main__"":
    num_ints = 10
    generate_random_integers(num_ints)
    ints = read_file()
    sorted_ints = sort_integers(ints)
    top_sum = find_sum_of_top_three(sorted_ints)
    print(""The sum of the top three largest numbers is"", top_sum)
```
