import json
from hashlib import sha256
import hmac
from base64 import b64encode, b64decode
import jwt

class JWTValidator:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def validate(self, token, claims=None):
        try:
            payload = jwt.decode(token, self.secret_key, algorithms=['HS256'])
            if claims is not None:
                for key, value in claims.items():
                    if payload[key] != value:
                        raise ValueError('Invalid claim')
        except jwt.exceptions.DecodeError as e:
            print(f'JWT decode error: {e}')
            return False
        except KeyError as e:
            print(f'Missing claim: {e}')
            return False
        except ValueError as e:
            print(f'Invalid value for claim: {e}')
            return False
        return True

class HMAC:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def create_hmac(self, message):
        hmac_obj = hmac.new(self.secret_key.encode(), msg=message.encode(), digestmod=sha256)
        return b64encode(hmac_obj.digest()).decode()

    def verify_hmac(self, message, signature):
        calculated_signature = self.create_hmac(message)
        if calculated_signature == signature:
            return True
        else:
            print('HMAC verification failed')
            return False

class UserManager:
    def __init__(self, users):
        self.users = users

    def add_user(self, user_id, role='reader'):
        if user_id not in self.users:
            self.users[user_id] = {'role': role}
        else:
            print('User already exists')

    def get_user(self, user_id):
        return self.users.get(user_id)

class ACL:
    def __init__(self, roles):
        self.roles = roles

    def get_role(self, user_id):
        return self.users.get(user_id, 'reader')

    def has_permission(self, role, permission):
        return role in self.roles and permission in self.roles[role]

class TokenRevoker:
    def __init__(self, tokens):
        self.tokens = tokens

    def revoke_token(self, token):
        if token in self.tokens:
            del self.tokens[token]
        else:
            print('Token already revoked')

class SecureAuthenticator:
    def __init__(self, secret_key, users, roles, tokens):
        self.secret_key = secret_key
        self.users = UserManager(users)
        self.roles = ACL(roles)
        self.tokens = TokenRevoker(tokens)

    def authenticate(self, user_id, password):
        if not self.users.get_user(user_id):
            print('Invalid username')
            return False

        # Perform password authentication here...

        if not self.verify_password(user_id, password):
            print('Invalid password')
            return False

        user = self.users.get_user(user_id)
        role = self.roles.get_role(user_id)
        token = create_token(user_id, role, self.secret_key)
        self.tokens.add_token(token)
        return token

    def verify_password(self, user_id, password):
        # Perform password verification here...
        if password == 'correct_password':
            return True
        else:
            print('Invalid password')
            return False

    def revoke_token(self, token):
        self.tokens.revoke_token(token)

    def check_token(self, token):
        if not self.tokens.get_token(token):
            print('Invalid token')
            return False

        user_id = get_user_id_from_token(token, self.secret_key)
        role = self.roles.get_role(user_id)
        if not self.verify_token(token, role, self.secret_key):
            print('Invalid token')
            return False

        return True

    def get_user_id(self, token):
        return get_user_id_from_token(token, self.secret_key)

    def get_role(self, token):
        user_id = get_user_id_from_token(token, self.secret_key)
        return self.roles.get_role(user_id)

    def verify_token(self, token, role, secret_key):
        payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        if 'role' not in payload or 'exp' not in payload:
            print('Invalid JWT token')
            return False

        if role != payload['role']:
            print('Unauthorized access attempt')
            return False

        if is_token_expired(payload['exp']):
            print('Token expired')
            return False

        return True

    def get_tokens(self):
        return self.tokens.tokens

    def has_permission(self, user_id, permission):
        role = self.roles.get_role(user_id)
        if not role:
            print('Invalid user ID')
            return False

        return self.roles.has_permission(role, permission)

def create_token(user_id, role, secret_key):
    payload = {
        'user_id': user_id,
        'role': role,
        'exp': get_token_expiration()
    }
    return jwt.encode(payload, secret_key, algorithm='HS256')

def get_user_id_from_token(token, secret_key):
    payload = jwt.decode(token, secret_key, algorithms=['HS256'])
    return payload['user_id']

def is_token_expired(expiration):
    now = datetime.now()
    token_expiration = datetime.strptime(expiration, '%Y-%m-%d %H:%M:%S')
    if now > token_expiration:
        return True
    else:
        return False

def get_token_expiration():
    now = datetime.now()
    expiration = now + timedelta(hours=1)
    return expiration.strftime('%Y-%m-%d %H:%M:%S')""]",0,[0],[],True,0,0,0,

