for (const auto& transaction : transactions) {
    // Calculate the total cost of the transaction
    double transactionCost = transaction.purchasePrice * transaction.numShares *
                             (1 + transaction.transactionFeePercentage / 100) +
                             transaction.numShares * transaction.marketImpactCostPerShare

column11:
// Calculate the total taxes paid on the transaction
double totalTaxes = transaction.purchasePrice * transaction.numShares *
                    (transaction.taxRate / 100)

column12:
// Calculate the profit from the transaction
double profit = (transaction.sellPrice - transaction.purchasePrice) *
                transaction.numShares - transactionCost - totalTaxes

column13:
// Check if the profit is greater than the minimum profit margin and greater than or equal to the minimum purchase price
if (profit >= minimumProfitMargin &&
    (transaction.purchasePrice * transaction.numShares) >= minimumPurchasePrice) {
    maxProfit += profit

