import json
from typing import Dict, Callable

class JsonParser:
    _registry: Dict[str, Callable[[], JsonParser]] = {}

    def __init__(self):
        pass

    @classmethod
    def register_factory(cls, id: str) -> None:
        cls._registry[id] = lambda: JsonParser()

    @classmethod
    def create_instance(cls, id: str) -> JsonParser:
        return cls._registry[id]()

    def to_json(self, data: Dict) -> str:
