import datetime
from typing import List

class GZIPCompressionState:
    def __init__(self, level: int, window_size: int):
        self.level = level
        self.window_size = window_size
        self.flushed = False
        self.timestamp = datetime.datetime.now()

def generate_gzip_compression_states(n: int) -> List[GZIPCompressionState]:
    compression_states = []
    for i in range(n):
        state = GZIPCompressionState(i % 10, i * 2 + 1)
        compression_states.append(state)
    return compression_states

def compress(data: bytes, compression_state: GZIPCompressionState) -> bytes:
    with gzip.GzipFile(fileobj=compression_state.window_size) as f:
        f.write(data)
    return data

def decompress(data: bytes, compression_state: GZIPCompressionState) -> bytes:
    with gzip.GzipFile(fileobj=compression_state.window_size) as f:
        return f.read()

