app = FastAPI()

class NFME_PDU(BaseModel):
    UEInformation: Dict[str, str]
    RX_UE_INFORMATION_TAGs: List[int]
    RNTI: int
    NFM_EDU_TAG: bool

@app.put(""/update-nfme-pdu"")
async def update_nfme_pdu(data: Dict):
    # Validate request body's content type and ensure it is JSON or another suitable format for easy parsing
    if not isinstance(data, dict) or ""UEInformation"" not in data or ""RX_UE_INFORMATION_TAGs"" not in data:
        raise HTTPException(status_code=400, detail=""Invalid request body"")

    # Check if the unique identifier provided exists in the system before proceeding with any updates
    if data[""UEInformation""][""UniqueID""] not in [pdu.UEInformation[""UniqueID""] for pdu in NFME_PDU]:
        raise HTTPException(status_code=404, detail=""Unable to find UEInformation with given UniqueID"")

    # Increment a unique tag counter for each entity in an array of NFME_PDU_T structures
    updated_pdu_list = []
    for pdu in NFME_PDU:
        updated_pdu = pdu.copy()
        if pdu.UEInformation[""UniqueID""] == data[""UEInformation""][""UniqueID""]:
            # Increment RX_UE_INFORMATION_TAGs and randomly assign RNTI values within specified ranges
            for tag in updated_pdu.RX_UE_INFORMATION_TAGs:
                if tag == ""RX_UE_INFORMATION_TAG"":
                    # Increment tag value by 1
                    tag += 1
                else:
                    # Randomly assign RNTI value within specified ranges
                    tag = random.randint(0, 10)
            updated_pdu.RNTI = random.randint(0, 100)
            updated_pdu.NFM_EDU_TAG = random.choice([True, False])
        updated_pdu_list.append(updated_pdu)

    # Log each update operation for debugging and auditing purposes
    for pdu in updated_pdu_list:
        logging.info(f""Updated UEInformation with UniqueID {pdu.UEInformation['UniqueID']}: New RX_UE_INFORMATION_TAGs = {pdu.RX_UE_INFORMATION_TAGs}, New RNTI = {pdu.RNTI}, New NFM_EDU_TAG = {pdu.NFM_EDU_TAG}"")

    return {""updated_nfme_pdus"": updated_pdu_list}

@app.delete(""/delete-nfme-pdu"")
async def delete_nfme_pdu(UniqueID: str):
    # Locate and retrieve necessary details about the resource needing deletion
    deleted_pdu = None
    for pdu in NFME_PDU:
        if pdu.UEInformation[""UniqueID""] == UniqueID:
            deleted_pdu = pdu
            break

    # Proceed to delete the resource from storage while handling any potential exceptions
    if deleted_pdu is not None:
        NFME_PDU.remove(deleted_pdu)
