def generate_weather_data(num_days, avg_temperature, weather_pattern):
    # Check that num_days is a positive integer
    if not isinstance(num_days, int) or num_days <= 0:
        raise ValueError(""Invalid number of days"")

    # Check that avg_temperature is a non-negative float
    if not isinstance(avg_temperature, float) or avg_temperature < 0:
        raise ValueError(""Invalid average temperature"")

    # Check that weather_pattern is an integer between 1 and 4
    if not isinstance(weather_pattern, int) or weather_pattern < 1 or weather_pattern > 4:
        raise ValueError(""Invalid weather pattern"")

    # Generate the weather data
    weather_data = []
    for i in range(num_days):
        temperature = round(avg_temperature + random.uniform(-2, 2), 1)
        while True:
            if temperature < 18 or temperature > 22:
                temperature = round(avg_temperature + random.uniform(-2, 2), 1)
            else:
                break
        weather_data.append({""day"": i+1, ""temperature"": temperature, ""weather"": [""Sunny"", ""Rainy"", ""Cloudy"", ""Snowy""][random.randint(0,3)]})

    # Sort the weather data by day number or temperature in ascending/descending order
