# Python function to read a file, sort its lines, and extract the sequence number from the last line
import os

def get_last_sequence_number(file_path):
  # Read the file contents into a list
  with open(file_path) as f:
    lines = [line.strip() for line in f]

  # Sort the lines by their sequence numbers
  sorted_lines = sorted(lines, key=lambda x: int(x.split("","")[0]))

  # Extract the last sequence number from the sorted list
  last_sequence_number = int(sorted_lines[-1].split("","")[0])

  return last_sequence_number
