                reader = csv.reader(f)
                rows = [row for row in reader]
                data += [{key: value for key, value in zip(rows[0], row)} for row in rows[1:]]

        # Merge the dictionaries into a single list of records
        merged_data = []
        for record in data:
            if record not in merged_data:
                merged_data.append(record)
            else:
                existing_record = merged_data[merged_data.index(record)]
                for key, value in record.items():
                    if key in existing_record and existing_record[key] != value:
                        existing_record[key] += value

        # Write the merged dataset back to a new CSV file in the specified directory
        with open('merged_data.csv', 'w') as f:
            writer = csv.writer(f)
            for record in merged_data:
                writer.writerow(record)
