import random
from typing import List

class NEID:
    def __init__(self):
        self.element_id = str(random.randint(10000, 99999))
        self.site_id = str(random.randint(1, 1000))
        self.network_type = random.choice(['LTE', '5G', 'Wi-Fi'])

def validate_neids(neids: List[NEID]) -> bool:
    for neid in neids:
        if not (1 <= int(neid.site_id) <= 1000):
            return False
        if neid.network_type not in ['LTE', '5G', 'Wi-Fi']:
            return False
    return True

def batch_insert_neids(neids: List[NEID], db_connection) -> bool:
    try:
        for neid in neids:
            sql = f""INSERT INTO network_elements (element_id, site_id, network_type) VALUES ('{neid.element_id}', '{neid.site_id}', '{neid.network_type}')""
            db_connection.execute(sql)
    except Exception as e:
        print(""Error occurred while inserting NEIDs into database"")
        return False
    return True
```
