import random
from typing import List, Dict

class WeatherDataGenerator:
    def __init__(self, count: int):
        self.count = count
        self.temperature_range = (0, 40)
        self.humidity_range = (0, 100)
        self.wind_speed_range = (0, 20)
        self.weather_data: List[Dict[str, float]] = []

    def Initialize(self):
        for _ in range(self.count):
            temperature = random.uniform(*self.temperature_range)
            humidity = random.uniform(*self.humidity_range)
            wind_speed = random.uniform(*self.wind_speed_range)
            self.weather_data.append({""temperature"": temperature, ""humidity"": humidity, ""wind_speed"": wind_speed})

    def GenerateTemperatureDelegate(self):
        return random.uniform(*self.temperature_range)

    def GenerateHumidityDelegate(self):
        return random.uniform(*self.humidity_range)

    def GenerateWindSpeedDelegate(self):
        return random.uniform(*self.wind_speed_range)

    def CreateWeatherDataPacket(self, location: List[float], timestamp: int):
        weatherPdu = {
            ""location"": location,
            ""timestamp"": timestamp,
            ""temperature"": self.GenerateTemperatureDelegate(),
            ""humidity"": self.GenerateHumidityDelegate(),
            ""wind_speed"": self.GenerateWindSpeedDelegate()
        }
        return weatherPdu
