// Define the function to calculate the md5 hash of a file
def calc_md5(filepath):
  # Open the file in binary mode
  with open(filepath, 'rb') as f:
    # Create an instance of the MD5 algorithm
    md5 = hashlib.md5()

    # Read data from the file and update the hash
    while True:
      data = f.read(1024)
      if not data:
        break
      md5.update(data)

    # Return the hexdigest of the hash
    return md5.hexdigest()

# Define a function to display real-time processing progress using tqdm
def display_progress(filepaths):
  # Create a progress bar to display real-time processing progress
  progress = tqdm.tqdm(total=100, unit='%')

  # Loop through the files and calculate their md5 hashes
  for filepath in filepaths:
    # Calculate the md5 hash of the file using the Python function
    md5_hash = calc_md5(filepath)

    # Update the progress bar with the current processing percentage
    progress.update(10)
