import json

class BloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.filter = [False] * (self.size / 8)

    def add(self, item):
        for i in range(self.hash_count):
            index = self.calculate_index(item, i)
            self.filter[index] = True

    def check(self, item):
        for i in range(self.hash_count):
            index = self.calculate_index(item, i)
            if not self.filter[index]:
                return False
        return True

    def calculate_index(self, item, hash_num):
        hash = hashlib.md5(item.encode()).hexdigest()
        index = int(hash[:16], 16) % (self.size / 8)
        return index

def add_to_bloom_filter(bloom_filter, item):
